beforeExample:
class MyEvent {}
class MyClass {
    void dispose(MyEvent event) { System.out.println("Disposing old method"); }
    // The new method must exist for compilation, even if it's the target of a rename.
    void treeCursorDispose(MyEvent event) { System.out.println("Disposing new method"); }

    void handleEvent(MyEvent event) {
        // Simplified context, focusing on the method call
        dispose(event); // This is the target match
    }
}

afterExample:
class MyEvent {}
class MyClass {
    void dispose(MyEvent event) { System.out.println("Disposing old method"); }
    void treeCursorDispose(MyEvent event) { System.out.println("Disposing new method"); }

    void handleEvent(MyEvent event) {
        treeCursorDispose(event); // This is the result of the transformation
    }
}

negativeExample:
class OtherObject {
    // A 'dispose' method with a different signature or context
    void dispose() { System.out.println("Other object dispose (no args)"); }
}

class AnotherClass {
    void someMethod() {
        OtherObject obj = new OtherObject();
        obj.dispose(); // This should NOT be changed because it has no arguments, not matching 'dispose($event)'
    }
}

